import { useEffect, useRef } from "react";


const CardItem_Map = (mapx,mapy,mlevel) => {

    const map = useRef();

    const {kakao} = window;
    //스크립트로 api가져오면 window전역객체로 분류.
    // 함수형 컴포넌트에서는 인식 못함 -> 때문에 변수선언.

    useEffect(() => {
        const options = {
            center : new kakao.maps.LatLng(mapx,mapy),
            level : mlevel
        }
        const box = new kakao.maps.Map(map.current,options);
        
    },[]);
    
    return (
        <div className="cardItemMap" ref={map} style="width:'100%',hegiht:'300px'">
            
        </div>
    );
}


export default CardItem_Map;
